--- a/mail/components/extensions/ExtensionMessages.sys.mjs
+++ b/mail/components/extensions/ExtensionMessages.sys.mjs
@@ -205,6 +205,15 @@ class WebExtMimeTreeEmitter extends MimeTreeEmitter {
         return getName(contentDisposition) || "ForwardedMessage.eml";
       }

+      // We also consider related (inline) attachments as attachments.
+      if (mimeTreePart.headers._rawHeaders.has("content-id")) {
+        return (
+          getName(contentDisposition) ||
+          mimeTreePart.headers.contentType.get("name") ||
+          ""
+        );
+      }
+
       if (
         /^attachment/i.test(contentDisposition) ||
         mimeTreePart.headers.contentType.type == "text/x-moz-deleted"
diff --git a/mail/components/extensions/parent/ext-messages.js b/mail/components/extensions/parent/ext-messages.js
index 6879b497e71..b5e234755e3 100644
--- a/mail/components/extensions/parent/ext-messages.js
+++ b/mail/components/extensions/parent/ext-messages.js
@@ -195,6 +195,13 @@ async function convertAttachment(msgHdr, mimeTreePart, extension) {

     rv.message = extension.messageManager.convert(attachedMsgHdr);
   }
+
+  // Include the content-Id, if available (for related parts).
+  if (mimeTreePart.headers._rawHeaders.has("content-id")) {
+    const cId = mimeTreePart.headers._rawHeaders.get("content-id")[0];
+    rv.contentId = cId.replace(/^<|>$/g, "");
+  }
+
   return rv;
 }

